import numpy as np
tb=[np.ones_like(t),t,t**2]
Pb={'P':P,'P2':P**2,'P3':P**3,'PlogP':P*np.log(P),'sqrtP':np.sqrt(P),'logP':np.log(P),'1/P':1/P,'expmP':np.exp(-P),'P*expmP':P*np.exp(-P),'P2/(1+P)':P**2/(1+P),'P/(1+P)':P/(1+P),'P/(1+P2)':P/(1+P**2)}
def run(names,tfuncs=tb):
    cols=[];nm=[]
    for n in names:
        for i,f in enumerate(tfuncs):
            cols.append(Pb[n]*f); nm.append(f"{n}*t{i}")
    A=np.vstack(cols).T
    c=np.linalg.lstsq(A,dP_dt,rcond=None)[0]
    r=dP_dt-A@c
    return np.mean(r**2)/np.var(dP_dt), nm, c
